// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "<![CDATA[" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("comNm")))) + "]]\u003e"; } },
        { childId: "__rb1", fn: function () { return "<![CDATA[" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("lstPayAmt1")))) + "]]\u003e"; } },
        { childId: "__rb2", fn: function () { return "<![CDATA[" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("lstPayAmt2")))) + "]]\u003e"; } },
        { childId: "__rb3", fn: function () { return "<![CDATA[" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("lstPayAmt3")))) + "]]\u003e"; } },
        { childId: "__rb4", fn: function () { return "<![CDATA[" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("lstPayAmt4")))) + "]]\u003e"; } },
        { childId: "__rb5", fn: function () { return "<![CDATA[" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("lstPayAmt5")))) + "]]\u003e"; } },
        { childId: "__rb6", fn: function () { return "<![CDATA[" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("lstPayAmt6")))) + "]]\u003e"; } },
        { childId: "__rb7", fn: function () { return "<![CDATA[" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("lstPayAmt7")))) + "]]\u003e"; } },
        { childId: "__rb8", fn: function () { return "<![CDATA[" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("lstPayAmt8")))) + "]]\u003e"; } },
        { childId: "__rb9", fn: function () { return "<![CDATA[" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("lstPayAmt9")))) + "]]\u003e"; } },
        { childId: "__rb10", fn: function () { return "<![CDATA[" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("feeNm")))) + "]]\u003e"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil54300.onpageload' });
    }
};


